<?php
declare(strict_types=1);namespace Haerriz\AgenticCommerce\Test\Unit\Model\Resilience;
use Haerriz\AgenticCommerce\Model\Config;use Haerriz\AgenticCommerce\Model\Resilience\CircuitBreaker;use Magento\Framework\App\CacheInterface;use PHPUnit\Framework\TestCase;
class CircuitBreakerTest extends TestCase{public function testOpensAfterThresholdAndResets():void{$data=[];$cache=$this->createMock(CacheInterface::class);$cache->method('load')->willReturnCallback(function($k)use(&$data){return $data[$k]??false;});$cache->method('save')->willReturnCallback(function($v,$k)use(&$data){$data[$k]=$v;return true;});$cache->method('remove')->willReturnCallback(function($k)use(&$data){unset($data[$k]);return true;});$c=$this->createMock(Config::class);$c->method('isProviderCircuitBreakerEnabled')->willReturn(true);$c->method('getProviderCircuitBreakerThreshold')->willReturn(2);$c->method('getProviderCircuitBreakerCooldown')->willReturn(60);$b=new CircuitBreaker($cache,$c);$b->failure('x',1);self::assertFalse($b->isOpen('x',1));$b->failure('x',1);self::assertTrue($b->isOpen('x',1));$b->success('x',1);self::assertFalse($b->isOpen('x',1));}}
